attempts.query:
PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?v a energia:DetectedVenting ; energia:inConcession ?c ; energia:date ?d .
  FILTER(STR(?d) >= "2024-01-01")
  FILTER NOT EXISTS {
    ?p a energia:PipelineLink ; energia:aboutConcession ?c ; energia:distanceKm ?km .
    FILTER(?km < 10)
  }
}
